# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MONOMER - POLİMER İLİŞKİSİ: DEHİDRASYON SENTEZİ VE HİDROLİZ</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">DEHİDRASYON SENTEZİ (YAPIM)</text>\n  <text x="35" y="94" font-size="11" font-weight="bold" fill="#1e3a8a">n (Monomer) → Polimer + (n - 1) H2O</text>\n  <text x="35" y="118" font-size="10.5" fill="#1d4ed8">• Küçük yapı taşları (monomerler) kovalent bağlarla</text>\n  <text x="43" y="134" font-size="10.5" fill="#1d4ed8">birleşerek büyük molekülleri (polimer) oluşturur.</text>\n  <text x="35" y="156" font-size="10.5" fill="#1d4ed8">• Kurulan her bir bağ için 1 molekül su açığa çıkar.</text>\n  <text x="35" y="178" font-size="10.5" font-weight="bold" fill="#b91c1c">• ATP (enerji) harcanır; hücre içinde gerçekleşir.</text>\n  <text x="35" y="200" font-size="10.5" fill="#1d4ed8">• Bağ sayısı = Açığa çıkan su sayısı = n - 1</text>\n  <text x="35" y="220" font-size="10.5" fill="#1d4ed8">• Hücrenin ozmotik basıncını azaltır, turgoru artırır.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">HİDROLİZ TEPKİMESİ (YIKIM / SİNDİRİM)</text>\n  <text x="375" y="94" font-size="11" font-weight="bold" fill="#78350f">Polimer + (n - 1) H2O → n (Monomer)</text>\n  <text x="375" y="118" font-size="10.5" fill="#92400e">• Büyük organik moleküller su kullanılarak</text>\n  <text x="383" y="134" font-size="10.5" fill="#92400e">enzimler yardımıyla monomerlerine parçalanır.</text>\n  <text x="375" y="156" font-size="10.5" fill="#92400e">• Kovalent bağlar koparılırken su harcanır.</text>\n  <text x="375" y="178" font-size="10.5" font-weight="bold" fill="#15803d">• ATP harcanmaz ve üretilmez (ısı enerjisi yeterlidir).</text>\n  <text x="375" y="200" font-size="10.5" fill="#92400e">• Hem hücre içinde hem hücre dışında gerçekleşebilir.</text>\n  <text x="375" y="220" font-size="10.5" fill="#92400e">• Hücredeki su miktarını azaltır, ozmotik basıncı artırır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KARBOHİDRATLAR: MONOSAKKARİTLER VE DİSAKKARİTLER</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">1. MONOSAKKARİTLER (TEK ŞEKERLİLER)</text>\n  <text x="35" y="92" font-size="10.5" font-weight="bold" fill="#14532d">• Sindirilmezler, hücre zarından doğrudan geçerler.</text>\n  <text x="35" y="112" font-size="10.5" fill="#166534">• Glikozit bağı içermezler; suda çözünürler.</text>\n  <text x="35" y="136" font-size="11" font-weight="bold" fill="#15803d">A) Pentozlar (5 Karbonlular - Yapısaldır):</text>\n  <text x="43" y="154" font-size="10.5" fill="#166534">- Riboz (C5H10O5): RNA ve ATP yapısına katılır.</text>\n  <text x="43" y="170" font-size="10.5" fill="#166534">- Deoksiriboz (C5H10O4): DNA yapısına katılır (1 O eksik).</text>\n  <text x="35" y="194" font-size="11" font-weight="bold" fill="#15803d">B) Heksozlar (6 Karbonlu İzomerler - C6H12O6):</text>\n  <text x="43" y="212" font-size="10.5" fill="#166534">- Glikoz (Kan/Üzüm şekeri - temel enerji kaynağı)</text>\n  <text x="43" y="228" font-size="10.5" fill="#166534">- Fruktoz (Meyve şekeri) · Galaktoz (Süt şekeri)</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">2. DİSAKKARİTLER (ÇİFT ŞEKERLİLER - C12H22O11)</text>\n  <text x="375" y="92" font-size="10.5" fill="#581c87">• İki heksozun 1 glikozit bağı ile birleşmesiyle oluşur.</text>\n  <text x="375" y="110" font-size="10.5" fill="#581c87">• Hücre zarından doğrudan geçemez, sindirilmeleri gerekir.</text>\n  <rect x="375" y="124" width="290" height="102" rx="8" fill="#ffffff" stroke="#d8b4fe" stroke-width="1.5"/>\n  <text x="385" y="146" font-size="10.5" font-weight="bold" fill="#6b21a8">• Glikoz + Glikoz → MALTOZ (Arpa şekeri) + H2O</text>\n  <text x="385" y="172" font-size="10.5" font-weight="bold" fill="#6b21a8">• Glikoz + Fruktoz → SÜKROZ / SAKKAROZ (Çay) + H2O</text>\n  <text x="385" y="198" font-size="10.5" font-weight="bold" fill="#b91c1c">• Glikoz + Galaktoz → LAKTOZ (Süt - Hayvansal) + H2O</text>\n  <text x="385" y="218" font-size="10" fill="#581c87">(Maltoz ve Sükroz bitkisel, Laktoz hayvansal sentezlidir.)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">POLİSAKKARİTLER (ÇOK ŞEKERLİLER): DEPO VE YAPISAL TÜRLER</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">DEPO POLİSAKKARİTLERİ</text>\n  <text x="35" y="94" font-size="11" font-weight="bold" fill="#1e3a8a">1. NİŞASTA (Bitkisel Depo):</text>\n  <text x="43" y="112" font-size="10.5" fill="#1d4ed8">• Bitki ve alglerde fotosentez sonucu üretilen glikozun</text>\n  <text x="43" y="128" font-size="10.5" fill="#1d4ed8">lökoplastlarda depolanmış hâlidir (İyotla mavi-mor renk).</text>\n  <text x="35" y="156" font-size="11" font-weight="bold" fill="#1e3a8a">2. GLİKOJEN (Hayvansal, Mantar ve Bakteri Deposu):</text>\n  <text x="43" y="174" font-size="10.5" fill="#1d4ed8">• Hayvanlarda (karaciğer ve çizgili kaslarda), mantarlarda,</text>\n  <text x="43" y="190" font-size="10.5" fill="#1d4ed8">bakteri ve arkelerde glikozun dallanmış depo şeklidir.</text>\n  <text x="43" y="212" font-size="10" font-weight="bold" fill="#b91c1c">• Karaciğer glikojeni kan şekerini ayarlar; kas glikojeni</text>\n  <text x="43" y="226" font-size="10" font-weight="bold" fill="#b91c1c">kana verilmez, kas kasılmasında tüketilir.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">YAPISAL POLİSAKKARİTLER</text>\n  <text x="375" y="94" font-size="11" font-weight="bold" fill="#991b1b">3. SELÜLOZ (Bitkisel Hücre Çeperi):</text>\n  <text x="383" y="112" font-size="10.5" fill="#7f1d1d">• Bitki hücre duvarının temel bileşenidir; suda çözünmez.</text>\n  <text x="383" y="128" font-size="10.5" fill="#7f1d1d">• İnsanlar sindiremez ancak bağırsakta mukus salgılatarak</text>\n  <text x="383" y="144" font-size="10.5" fill="#7f1d1d">sindirim kanalının sağlıklı çalışmasını sağlar.</text>\n  <text x="375" y="170" font-size="11" font-weight="bold" fill="#991b1b">4. KİTİN (Azotlu Yapısal Polisakkarit):</text>\n  <text x="383" y="188" font-size="10.5" fill="#7f1d1d">• Yapısında C, H, O yanında AZOT (N) bulunduran tek</text>\n  <text x="383" y="204" font-size="10.5" fill="#7f1d1d">polisakkarittir. Mantar hücre duvarı ile eklem bacaklıların</text>\n  <text x="383" y="220" font-size="10.5" fill="#7f1d1d">dış iskeletini ve ameliyat ipliklerini oluşturur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
